import{_ as o,o as a,c as l,a2 as i}from"./chunks/framework.mRCPFc5l.js";const E=JSON.parse('{"title":"Environment Variables","description":"","frontmatter":{"title":"Environment Variables"},"headers":[],"relativePath":"operations/environment-variables.md","filePath":"operations/environment-variables.md","lastUpdated":1787839527000}'),r={name:"operations/environment-variables.md"};function t(n,e,d,c,_,s){return a(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="environment-variables" tabindex="-1">Environment-Variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment-Variables&quot;">​</a></h1><h2 id="目的" tabindex="-1">目的 <a class="header-anchor" href="#目的" aria-label="Permalink to &quot;目的&quot;">​</a></h2><p>整理本專案使用的環境變數命名規則、用途與建議覆寫方式，避免：</p><ul><li>把 secret 值提交到 Git</li><li>在部署/CI 時因環境變數缺失導致 fail-closed 行為</li></ul><h2 id="適用範圍" tabindex="-1">適用範圍 <a class="header-anchor" href="#適用範圍" aria-label="Permalink to &quot;適用範圍&quot;">​</a></h2><ul><li>本機開發（frontend/backend）</li><li>CI / Playwright（以 workflow 為準）</li><li>需要 debug/觀察 bank-sync/載具同步行為時</li></ul><h2 id="你要使用的檔案" tabindex="-1">你要使用的檔案 <a class="header-anchor" href="#你要使用的檔案" aria-label="Permalink to &quot;你要使用的檔案&quot;">​</a></h2><ul><li>前端範本：<a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/frontend/.env.example" target="_blank" rel="noreferrer"><code>frontend/.env.example</code></a></li><li>後端範本：<a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/backend/.env.example" target="_blank" rel="noreferrer"><code>backend/.env.example</code></a></li><li>本機調試覆寫：通常用 gitignored 的「覆寫檔」或「自建 local env」</li></ul><h2 id="前端-vite-重點" tabindex="-1">前端（VITE_*）重點 <a class="header-anchor" href="#前端-vite-重點" aria-label="Permalink to &quot;前端（VITE_*）重點&quot;">​</a></h2><p>前端所有控制項都以 <code>VITE_*</code> 為主；Wiki 只列「變數名稱與用途」，不收錄任何真實 secret 值。</p><ol><li>API base URL / 功能開關（例如 bank-sync）</li><li>Google Oauth / e-invoice 相關配置</li><li>Debug-only：僅在 DEV/debug 開啟 console trace（不建議上線後依賴）</li></ol><p>常見（依 <a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/frontend/.env.example" target="_blank" rel="noreferrer"><code>frontend/.env.example</code></a>）：</p><ul><li><code>VITE_SHARED_LEDGER_API_BASE_URL</code>：shared ledger/共同帳本後端 API base URL</li><li><code>VITE_GOOGLE_WEB_CLIENT_ID</code>：Google Sign-In 的 Web client id</li><li><code>VITE_BANK_SYNC_FEATURE_ENABLED</code>：bank-sync 入口是否顯示（Feature flag）</li><li><code>VITE_BANK_SYNC_ENABLE_UNSUPPORTED_REAL_PROVIDERS</code>：原生銀行自動化第二道開關。<strong>兩個都要開</strong>，功能頁才會出現銀行同步且 native 路徑才會跑；只開第一個不夠</li><li><code>VITE_BANK_SYNC_API_BASE_URL</code>：bank-sync 相關 API base URL</li><li><code>VITE_EINVOICE_CLIENT_SHARED_KEY</code>：e-invoice/載具流程的前端共享 key（server 端需同值）</li><li><code>VITE_EINVOICE_API_BASE_URL</code>：e-invoice/載具 API base URL</li><li><code>VITE_GOOGLE_OAUTH_API_ORIGIN</code>：Google OAuth API 的 origin（production 時影響走哪個網域）</li><li><code>VITE_WEB_HASH_ROUTER</code>：Hosted GitHub Pages 巢狀 SPA hash router</li></ul><h2 id="後端-非-vite-重點" tabindex="-1">後端（非 VITE_*）重點 <a class="header-anchor" href="#後端-非-vite-重點" aria-label="Permalink to &quot;後端（非 VITE_*）重點&quot;">​</a></h2><ol><li>Node server port / database file</li><li>Auth 與 rate limiting</li><li>Google Oauth client secret（必要時）</li><li>銀行/載具同步的 client shared key（fail-closed 用）</li></ol><p>常見（依 <a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/backend/.env.example" target="_blank" rel="noreferrer"><code>backend/.env.example</code></a>）：</p><ul><li><code>HOST</code> / <code>PORT</code>：後端监听設定（預設 <code>HOST=0.0.0.0</code>、<code>PORT=8787</code>）</li><li><code>SHARED_LEDGER_DB_FILE</code>：collab-store sqlite 檔案位置</li><li><code>GOOGLE_AUTH_WEB_CLIENT_ID</code>、<code>GOOGLE_OAUTH_CLIENT_SECRET</code>：Google OAuth 設定</li><li><code>EINVOICE_CLIENT_SHARED_KEY</code>、<code>BANK_SYNC_CLIENT_SHARED_KEY</code>、<code>GOOGLE_OAUTH_CLIENT_SHARED_KEY</code>：同步/驗證的 client shared key</li><li><code>LINEAR_API_KEY</code> / <code>LINEAR_TEAM_KEY</code>：Linear 整合用（可選）</li><li>SMTP：<code>SMTP_SERVER</code> / <code>SMTP_USER</code> / <code>SMTP_PASS</code> 等（密碼不要提交）</li></ul><h2 id="安全規範-避免知識漂移" tabindex="-1">安全規範（避免知識漂移） <a class="header-anchor" href="#安全規範-避免知識漂移" aria-label="Permalink to &quot;安全規範（避免知識漂移）&quot;">​</a></h2><ul><li>不提交 <code>.env</code>、<code>key.properties</code>、<code>.jks</code> 等密鑰檔（詳見 <a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer"><code>CONTRIBUTING.md</code></a>）</li><li>Wiki 只描述「變數用途/必填/預期行為」，不收錄真實 secret 值</li></ul><h2 id="引用來源" tabindex="-1">引用來源 <a class="header-anchor" href="#引用來源" aria-label="Permalink to &quot;引用來源&quot;">​</a></h2><ul><li><a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/frontend/.env.example" target="_blank" rel="noreferrer"><code>frontend/.env.example</code></a></li><li><a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/backend/.env.example" target="_blank" rel="noreferrer"><code>backend/.env.example</code></a></li><li><a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer"><code>CONTRIBUTING.md</code></a></li></ul>',21)])])}const h=o(r,[["render",t]]);export{E as __pageData,h as default};
